CREATE TABLE "cake_filling" (
    "cake_id" INTEGER NOT NULL,
    "filling_id" INTEGER NOT NULL,
    PRIMARY KEY ("cake_id", "filling_id")
);
CREATE INDEX "index_cake_filling_by_cake_id" ON "cake_filling" ("cake_id");
CREATE INDEX "index_cake_filling_by_filling_id" ON "cake_filling" ("filling_id");
CREATE TABLE "fruit" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL,
    "cake_id" INTEGER,
    PRIMARY KEY ("id")
);
CREATE INDEX "index_fruit_by_cake_id" ON "fruit" ("cake_id");
CREATE TABLE "cake" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE TABLE "filling" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(255) NOT NULL,
    PRIMARY KEY ("id")
);
